def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.minimum(np.maximum(x, lb), ub)

    def objective(params):
        return func(params)

    x = np.random.uniform(lb, ub, size=dim)
    best_x = x.copy()
    best_y = objective(x)

    for _ in range(budget):
        y = objective(x)
        if y < best_y:
            best_y = y
            best_x = x.copy()

        for i in range(dim):
            v = np.clip(x + 0.1 * rng.uniform(-1, 1), lb, ub)
            w = np.clip(x + 0.2 * rng.uniform(-1, 1), lb, ub)

            y_v = objective(v)
            y_w = objective(w)

            if y_v < best_y:
                best_y = y_v
                x = v.copy()
            elif y_w < best_y:
                best_y = y_w
                x = w.copy()

        x = clip(x)

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, a_min=lb, a_max=ub)

    def objective(x):
        return func(x)

    x = np.random.uniform(lb, ub, size=(dim,))
    T = 10.0
    cooling_rate = 0.99

    for _ in range(budget):
        x_new = x + rng.normal(0, 1, size=(dim,))
        x_new = clip(x_new)

        f_x = objective(x)
        f_x_new = objective(x_new)

        if f_x_new < f_x:
            x = x_new
        else:
            delta = f_x_new - f_x
            prob = np.exp(-delta / T)
            if rng.random() < prob:
                x = x_new

        T *= cooling_rate

    return clip(x)
